.pm-chapter-style-structural-metrics {
  --pm-ink: var(--ink, #1a1a1a);
  --pm-muted: var(--muted, #666);
  --pm-accent: var(--accent, #003366);
  --pm-warm: var(--warm, #cc0066);
  --pm-line: var(--line, #ddd);
  --pm-paper: var(--paper, #f5f5f5);

  font-family: serif;
  background-color: var(--pm-paper);
  color: var(--pm-ink);
  padding: 2rem 1rem;
  border: 1px solid var(--pm-line);
  margin: 1rem 0;
  box-sizing: border-box;
}

.pm-chapter-style-structural-metrics * {
  box-sizing: border-box;
}

.pm-header h2 {
  font-size: 1.5rem;
  margin-bottom: 0.5rem;
  color: var(--pm-accent);
  font-weight: 600;
}

.pm-lead {
  font-size: 1rem;
  line-height: 1.6;
  color: var(--pm-muted);
  margin-bottom: 2rem;
  max-width: 800px;
}

.pm-interaction-container {
  display: flex;
  flex-direction: column;
  gap: 2rem;
  max-width: 800px;
}

.pm-control-panel {
  background: #fff;
  padding: 1.5rem;
  border: 1px solid var(--pm-line);
  position: relative;
}

.pm-label {
  display: block;
  font-family: monospace;
  font-size: 0.9rem;
  margin-bottom: 1rem;
  color: var(--pm-ink);
}

.pm-value {
  font-weight: bold;
  color: var(--pm-accent);
}

input[type="range"] {
  width: 100%;
  accent-color: var(--pm-accent);
  cursor: pointer;
}

.pm-thresholds {
  position: relative;
  height: 1.5rem;
  margin-top: 0.5rem;
  border-top: 1px solid var(--pm-line);
}

.pm-mark {
  position: absolute;
  transform: translateX(-50%);
  font-size: 0.75rem;
  color: var(--pm-muted);
  font-family: monospace;
  top: 100%;
  padding-top: 0.25rem;
}

.pm-metrics-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 1rem;
}

.pm-metric-card {
  background: #fff;
  padding: 1rem;
  border-left: 4px solid var(--pm-muted);
  border: 1px solid var(--pm-line);
}

.pm-metric-card h3 {
  font-size: 1rem;
  margin: 0 0 0.5rem 0;
  font-family: monospace;
  color: var(--pm-ink);
}

.pm-status {
  font-size: 0.95rem;
  line-height: 1.4;
  min-height: 3rem;
  color: var(--pm-ink);
}

.pm-detail {
  font-size: 0.8rem;
  color: var(--pm-muted);
  margin: 0.5rem 0 0 0;
  font-family: monospace;
}

.pm-sources {
  display: flex;
  gap: 1rem;
  align-items: center;
  flex-wrap: wrap;
}

.pm-source-label {
  font-size: 0.9rem;
  color: var(--pm-muted);
  margin: 0;
}

.pm-btn {
  background: transparent;
  border: 1px solid var(--pm-accent);
  color: var(--pm-accent);
  padding: 0.5rem 1rem;
  font-size: 0.85rem;
  cursor: pointer;
  font-family: monospace;
  transition: background 0.2s;
}

.pm-btn:hover {
  background: var(--pm-accent);
  color: #fff;
}

.pm-btn:focus {
  outline: 2px solid var(--pm-warm);
  outline-offset: 2px;
}

.pm-limitation-note {
  background: #fff;
  border: 1px dashed var(--pm-muted);
  padding: 1rem;
  font-size: 0.85rem;
  color: var(--pm-muted);
}

.pm-limitation-note strong {
  color: var(--pm-ink);
}

@media (prefers-reduced-motion: reduce) {
  .pm-btn {
    transition: none;
  }
}

@media (max-width: 320px) {
  .pm-chapter-style-structural-metrics {
    padding: 1rem 0.5rem;
  }
  .pm-metrics-grid {
    grid-template-columns: 1fr;
  }
}

javascript:
(function() {
  'use strict';

  const container = document.querySelector('.pm-chapter-style-structural-metrics');
  if (!container) return;

  const slider = container.querySelector('#year-slider');
  const yearDisplay = container.querySelector('#year-display');
  const statusLength = container.querySelector('#status-length');
  const statusSpeed = container.querySelector('#status-speed');
  const statusRepetition = container.querySelector('#status-repetition');
  const sourceButtons = container.querySelectorAll('.pm-btn');

  // Logic based on Source S034 text claims
  function updateMetrics(year) {
    const y = parseInt(year, 10);
    yearDisplay.textContent = y;

    // Length: Similar till 1980, Pop significantly longer since then
    if (y < 1980) {
      statusLength.textContent = '流行与非流行趋势相似，稳步增加。';
      statusLength.style.color = 'var(--pm-muted)';
      container.querySelector('[data-metric="length"]').style.borderLeftColor = 'var(--pm-muted)';
    } else {
      statusLength.textContent = '流行歌曲显著长于非流行歌曲。';
      statusLength.style.color = 'var(--pm-accent)';
      container.querySelector('[data-metric="length"]').style.borderLeftColor = 'var(--pm-accent)';
    }

    // Speed: Pop slower till 1990, significantly faster since
    if (y < 1990) {
      statusSpeed.textContent = '流行歌曲相对较慢 (非流行约 0.6 词/秒)。';
      statusSpeed.style.color = 'var(--pm-muted)';
      container.querySelector('[data-metric="speed"]').style.borderLeftColor = 'var(--pm-muted)';
    } else {
      statusSpeed.textContent = '流行歌曲显著加快，超过非流行歌曲。';
      statusSpeed.style.color = 'var(--pm-warm)';
      container.querySelector('[data-metric="speed"]').style.borderLeftColor = 'var(--pm-warm)';
    }

    // Repetition: Pop higher except 1990-2000
    if (y >= 1990 && y <= 2000) {
      statusRepetition.textContent = '例外期：流行歌曲重复率未显著高于非流行。';
      statusRepetition.style.color = 'var(--pm-muted)';
      container.querySelector('[data-metric="repetition"]').style.borderLeftColor = 'var(--pm-muted)';
    } else {
      statusRepetition.textContent = '流行歌曲重复率始终高于非流行歌曲。';
      statusRepetition.style.color = 'var(--pm-accent)';
      container.querySelector('[data-metric="repetition"]').style.borderLeftColor = 'var(--pm-accent)';
    }
  }

  function handleSourceClick(e) {
    const sourceId = e.target.getAttribute('data-source');
    // Host kernel handles source navigation via data-source attribute
    // No action needed here per spec, but ensuring event is registered
    if (window.paperMindData && window.paperMindData.sources && window.paperMindData.sources[sourceId]) {
      // Visual feedback only
      e.target.style.background = 'var(--pm-accent)';
      e.target.style.color = '#fff';
      setTimeout(() => {
        e.target.style.background = '';
        e.target.style.color = '';
      }, 300);
    }
  }

  if (slider) {
    slider.addEventListener('input', function(e) {
      updateMetrics(e.target.value);
    });
    // Initialize
    updateMetrics(slider.value);
  }

  sourceButtons.forEach(btn => {
    btn.addEventListener('click', handleSourceClick);
  });

})();
